"""Casos SQL sintéticos; genera entradas, no declara resultados."""
import json
from pathlib import Path
R=Path(__file__).resolve().parent
cases=[]
def add(name,sql,state=None,category='integridad'):
    row=dict(nombre=name,sql=sql,categoria=category)
    if state:row['sqlstate']=state
    cases.append(row)

