add('Foto revocada sigue pudiendo eliminar metadata y análisis propios',"UPDATE public.patient_consents SET revoked_at=clock_timestamp() WHERE id=qa.id(91); DELETE FROM public.dental_photos WHERE id=qa.id(92); DO $$ BEGIN ASSERT NOT EXISTS(SELECT 1 FROM ml.analysis_authorizations WHERE id=qa.id(93)); ASSERT NOT EXISTS(SELECT 1 FROM ml.analysis_jobs WHERE id=qa.id(94)); END $$;")
add('Paciente puede borrar metadata propia tras revocar con RLS existente',"UPDATE public.patient_consents SET revoked_at=clock_timestamp() WHERE id=qa.id(91); SELECT qa.identity(1); SET LOCAL ROLE authenticated; DELETE FROM public.dental_photos WHERE id=qa.id(92); RESET ROLE; DO $$ BEGIN ASSERT NOT EXISTS(SELECT 1 FROM public.dental_photos WHERE id=qa.id(92)); END $$;",category='RLS existente y compatibilidad CASCADE')
add('Paciente lee solo su perfil por RLS',"SELECT qa.identity(1); SET LOCAL ROLE authenticated; DO $$ BEGIN ASSERT (SELECT count(*)=1 FROM public.profiles); ASSERT (SELECT count(*)=0 FROM public.profiles WHERE id=qa.id(2)); END $$;",category='RLS existente')
add('Paciente no puede modificar perfil ajeno',"SELECT qa.identity(1); SET LOCAL ROLE authenticated; DO $$ DECLARE n integer; BEGIN UPDATE public.profiles SET full_name='QA' WHERE id=qa.id(2); GET DIAGNOSTICS n=ROW_COUNT; ASSERT n=0; END $$;",category='RLS existente')
add('Cliente no puede editar app_metadata ni elevar rol',"SELECT qa.identity(1); SET LOCAL ROLE authenticated; UPDATE auth.users SET raw_app_meta_data='{}' WHERE id=qa.id(1);",'42501','permisos SQL')
for label,role,user,claim in [('visitante','anon',1,'paciente'),('paciente','authenticated',1,'paciente'),('odontólogo','authenticated',4,'odontologo'),('superusuario','authenticated',6,'superusuario')]:
    add(label+': ACL clínica bloquea acceso directo',f"SELECT qa.identity({user},'{claim}'); SET LOCAL ROLE {role}; SELECT * FROM clinical.clinical_encounters;",'42501','permisos SQL')
    add(label+': RLS deniega las 21 tablas aun con SELECT temporal',f"GRANT USAGE ON SCHEMA clinical,ml TO {role}; GRANT SELECT ON ALL TABLES IN SCHEMA clinical,ml TO {role}; SELECT qa.identity({user},'{claim}'); SET LOCAL ROLE {role}; DO $$ DECLARE t record; n bigint; BEGIN FOR t IN SELECT schemaname,tablename FROM pg_tables WHERE schemaname IN ('clinical','ml') LOOP EXECUTE format('SELECT count(*) FROM %I.%I',t.schemaname,t.tablename) INTO n; ASSERT n=0; END LOOP; END $$;",category='RLS propuesta default-deny')
add('INSERT clínico queda bloqueado por RLS con privilegio temporal',"GRANT USAGE ON SCHEMA clinical TO authenticated; GRANT INSERT ON clinical.clinics TO authenticated; SELECT qa.identity(6,'superusuario'); SET LOCAL ROLE authenticated; INSERT INTO clinical.clinics(id,name) VALUES(qa.id(999),'QA');",'42501','RLS propuesta default-deny')
add('Superusuario no puede modificar auditoría clínica',"SELECT qa.identity(6,'superusuario'); SET LOCAL ROLE authenticated; UPDATE clinical.clinical_access_audit SET outcome='allowed';",'42501','permisos SQL')
add('service_role no recibe acceso clínico por ACL',"SET LOCAL ROLE service_role; SELECT * FROM clinical.clinical_encounters;",'42501','permisos SQL; no evidencia RLS')
